// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address target) public {
        vm.assume(amount > 0);
        vm.assume(target != address(0) && target != address(c));
        Reverter reverter = new Reverter();
        address adversary = address(reverter);
        vm.deal(address(c), amount);
        vm.prank(address(this));
        bool ok = true;
        try c.sendMoney(adversary, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            assertEq(adversary.balance, amount);
        } else {
            assertEq(adversary.balance, 0);
        }
    }
}
contract Reverter {
    fallback() external payable {
        revert("adversarial revert");
    }
}
